/* Cache pings only for a real change (round 54, Vercel costs; run after 179). Part 179's triggers on products, product_variants, inventory_levels, product_collections and product_collection_items ping /api/internal/invalidate after every row write, which expires the store's website, creator page and Explore caches and makes the next visitors render them again. An UPDATE that changes nothing (a job writing the same values back, or only touching updated_at) pinged too. This part replaces only the trigger function: an UPDATE whose row is the same apart from updated_at now sends nothing; inserts, deletes and every real change ping exactly as before. The triggers themselves are not touched. Until it runs, every write pings, as today. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_cache_ping() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE r jsonb; v_kind text := TG_ARGV[0]; v_creator uuid; v_product uuid; v_slug text; v_url text; v_secret text; v_key text; BEGIN IF TG_OP = 'UPDATE' AND (to_jsonb(OLD) - 'updated_at') = (to_jsonb(NEW) - 'updated_at') THEN RETURN NULL; END IF; IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RETURN NULL; END IF; SELECT c.url, c.secret INTO v_url, v_secret FROM public.storelib_cache_invalidation c WHERE c.id; IF coalesce(v_url, '') !~ '^https?://' OR coalesce(v_secret, '') = '' THEN RETURN NULL; END IF; BEGIN IF TG_OP = 'DELETE' THEN r := to_jsonb(OLD); ELSE r := to_jsonb(NEW); END IF; IF v_kind = 'product' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; v_product := nullif(r ->> 'id', '')::uuid; v_slug := r ->> 'slug'; ELSIF v_kind = 'variant' THEN v_product := nullif(r ->> 'product_id', '')::uuid; SELECT p.creator_id, p.slug INTO v_creator, v_slug FROM public.products p WHERE p.id = v_product; ELSIF v_kind = 'inventory' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; SELECT v.product_id, p.slug INTO v_product, v_slug FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = nullif(r ->> 'variant_id', '')::uuid; ELSIF v_kind = 'collection' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; IF v_creator IS NULL THEN SELECT c.creator_id INTO v_creator FROM public.product_collections c WHERE c.id = nullif(r ->> 'collection_id', '')::uuid; END IF; END IF; IF v_creator IS NULL THEN RETURN NULL; END IF; v_key := 'storelib_cache_ping.k' || md5(v_kind || ':' || v_creator::text || ':' || coalesce(v_product::text, '')); IF current_setting(v_key, true) = '1' THEN RETURN NULL; END IF; PERFORM set_config(v_key, '1', true); PERFORM net.http_post(url := v_url, body := jsonb_build_object('creatorId', v_creator, 'kind', v_kind, 'productId', v_product, 'slug', v_slug, 'op', TG_OP), params := '{}'::jsonb, headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret), timeout_milliseconds := 3000); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'storelib cache ping skipped: %', SQLERRM; END; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.storelib_cache_ping() FROM PUBLIC, anon, authenticated;
notify pgrst, 'reload schema';
